var a=UnityEngine.Object.FindObjectsByType<CampusRift.UI.ComboGraphic>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None);var results=new System.Collections.Generic.List<string>();foreach(var g in a){if(g.name.Contains("burst")||g.name.Contains("icon")||g.name.Contains("dot"))results.Add(g.name+" active="+g.isActiveAndEnabled+" renderer="+(g.GetComponent<UnityEngine.CanvasRenderer>()!=null)+" rect="+g.rectTransform.rect+" color="+g.color+" parent="+g.transform.parent.name);}
var u=UnityEngine.Object.FindObjectsByType<CampusRift.UI.GenerationChainUI>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None);foreach(var x in u)results.Add("GenerationUI active="+x.isActiveAndEnabled+" parent="+x.transform.parent.name);
return results;
